import java.io.*;
import java.util.regex.*;

public class Main {

    public static void debug(Object data, boolean die) {
        System.out.println("<pre>");
        if (data instanceof Object[]) {
            for (Object o : (Object[]) data) {
                System.out.println(o);
            }
        } else {
            System.out.println(String.valueOf(data));
        }
        if (die) {
            System.exit(0);
        }
        System.out.println("</pre>");
    }

    public static BufferedReader stdin() {
        try {
            File file = new File("data.txt");
            if (file.exists() && file.isFile()) {
                return new BufferedReader(new FileReader(file));
            }
        } catch (IOException ignored) {
        }
        return new BufferedReader(new InputStreamReader(System.in));
    }

    public static String g(BufferedReader stdin) throws IOException {
        String line = stdin.readLine();
        return line == null ? "" : line.trim();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader stdin = stdin();

        String id = g(stdin);

        String word = "[a-z0-9_]{1,16}";
        Pattern pattern = Pattern.compile("^" + word + "@((" + word + "\\.)*" + word + ")(/" + word + ")?$", Pattern.CASE_INSENSITIVE);
        Matcher matcher = pattern.matcher(id);

        boolean correct = matcher.matches();
        if (correct) {
            String group1 = matcher.group(1);
            correct = group1 != null && group1.length() > 0 && group1.length() < 33;
        }

        System.out.print(correct ? "YES" : "NO");
    }
}

